def upgrade():
    for path in sorted((ROOT / 'catalogs/methods').glob('*.json')):
        card = json.loads(path.read_text())
        conditions, contraindications, cost, experiment = DETAILS[card['id']]
        card.update(version=2, conditions=[conditions], contraindications=[contraindications], constraints=contraindications,
                    cost=cost, minimum_experiment=experiment, applicability_rules=[],
                    review_status='project_hypothesis_with_exact_source_links',
                    evidence_policy='API properties are exact quotations/signatures of supporting sections. This recommendation is a project hypothesis, not a measured or universal improvement.')
        if card['id']=='budget': card['references']=['resource_contract']
        if card['id']=='target_encoding':
            card['applicability_rules']=[{'field':'validation','op':'not_in','value':['temporal','time','group','grouped'],'reason':'Random cross-fitting does not preserve temporal/group boundaries.'}]
        card['supporting_sections']=[{'reference_id':ref,'required_verification':'exact_source_quote_and_version','semantic_scope':'API capability supporting the proposed experiment; no general performance claim'} for ref in card['references']]
        path.write_text(json.dumps(card,ensure_ascii=False,sort_keys=True,indent=2)+'\n')

if __name__=='__main__': upgrade()
